# >>> CHOICES
_choice_ffprobe_decoder() {
    ffprobe -decoders 2>/dev/null | gawk '
        {
            line = $0
            sub(/^[[:space:]]+/, "", line)
            if (line !~ /^[VAS][.FSXBD]{5}[[:space:]]+[[:alnum:]_.+-]+/) {
                next
            }
            split(line, fields, /[[:space:]]+/)
            print fields[2]
            emitted++
            if (emitted >= 500) {
                exit
            }
        }
    '
}

_choice_ffprobe_format() {
    ffprobe -formats 2>/dev/null | gawk '
        $1 ~ /^[DEd.]+$/ && $1 ~ /D/ {
            name = ($2 == "d" ? $3 : $2)
            if (name !~ /^[[:alnum:]_.+-]+(,[[:alnum:]_.+-]+)*$/) {
                next
            }
            count = split(name, names, ",")
            for (i = 1; i <= count && emitted < 500; i++) {
                print names[i]
                emitted++
            }
        }
    '
}

_choice_ffprobe_output_format() {
    printf '%s\n' default compact csv flat ini json xml
}

_choice_ffprobe_show_entries() {
    ffprobe -sections 2>/dev/null | gawk '
        {
            line = $0
            sub(/^[[:space:]]+/, "", line)
            if (line !~ /^[.WASVT]{4}[[:space:]]+[[:alnum:]_.\/-]+/) {
                next
            }
            split(line, fields, /[[:space:]]+/)
            print fields[2]
            emitted++
            if (emitted >= 500) {
                exit
            }
        }
    '
}

_choice_ffprobe_sinks() {
    _helper_ffprobe_devices E
}

_choice_ffprobe_sources() {
    _helper_ffprobe_devices D
}

_helper_ffprobe_devices() {
    local capability="$1"
    ffprobe -devices 2>/dev/null | gawk -v capability="$capability" '
        $1 ~ /^[DE.]+$/ {
            if (capability == "D" && $1 !~ /D/) {
                next
            }
            if (capability == "E" && $1 !~ /E/) {
                next
            }
            name = ($2 == "d" ? $3 : $2)
            if (name !~ /^[[:alnum:]_.+-]+(,[[:alnum:]_.+-]+)*$/) {
                next
            }
            count = split(name, names, ",")
            for (i = 1; i <= count && emitted < 100; i++) {
                print names[i]
                emitted++
            }
        }
    '
}
